begin;
create function public.referral_context(p_referral uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare r public.referrals;s public.submissions;result jsonb;begin
 select * into r from public.referrals where id=p_referral;select * into s from public.submissions where id=r.submission_id;
 if not public.can_read_submission(s.id) then raise exception 'context forbidden';end if;
 select jsonb_build_object('student_name',p.display_name,'degree',p.degree,'event_title',e.title,'deadline',s.deadline_snapshot,'attendance',coalesce(a.confirmed,false),'review_hours',s.policy_snapshot->'review_hours','history',(select coalesce(jsonb_agg(jsonb_build_object('outcome',aa.outcome,'score',aa.score,'feedback',aa.feedback,'created_at',aa.created_at,'attachment_id',aa.attachment_id) order by aa.created_at),'[]'::jsonb) from public.assessments aa join public.referrals rr on rr.id=aa.referral_id where rr.submission_id=s.id)) into result from public.profiles p join public.events e on e.id=s.event_id left join public.attendance a on a.event_id=e.id and a.student_id=p.id where p.id=s.student_id;return result;
end; $$;
create function public.cancel_registration(p_event uuid) returns void language plpgsql security definer set search_path='' as $$ begin update public.registrations set status='cancelled' where event_id=p_event and student_id=auth.uid() and not exists(select 1 from public.attendance where event_id=p_event and student_id=auth.uid() and confirmed);end; $$;
create function public.configure_certificate(p_kind text,p_policy uuid,p_minimum integer,p_approved boolean,p_reason text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.has_role('admin') or length(p_reason)<5 then raise exception 'global academic authority and reason required';end if;perform set_config('utr.reason',p_reason,true);insert into public.certificate_rules(kind,policy_id,minimum_events,approved) values(p_kind,p_policy,p_minimum,p_approved) on conflict(kind) do update set policy_id=excluded.policy_id,minimum_events=excluded.minimum_events,approved=excluded.approved;end; $$;
create trigger cert_rule_audit after insert or update on public.certificate_rules for each row execute function public.audit_change();
revoke all on function public.referral_context(uuid),public.cancel_registration(uuid),public.configure_certificate(text,uuid,integer,boolean,text) from public,anon;
grant execute on function public.referral_context(uuid),public.cancel_registration(uuid),public.configure_certificate(text,uuid,integer,boolean,text) to authenticated;
commit;
